const paletteOptions={
sage:{name:'Sage & paper',note:'Warm, quiet, and editorial. Closest to the workspace you selected.',colors:['#f5f3ed','#fffefa','#303b30','#657345','#e8ecdf','#5c6756','#d6dbcd'],dark:false},
cobalt:{name:'Porcelain & cobalt',note:'Crisp neutral surfaces with a decisive blue action color.',colors:['#f3f5f9','#ffffff','#202c43','#3158b8','#e8eefb','#5c6980','#d6deec'],dark:false},
clay:{name:'Sand & terracotta',note:'A warmer, more tactile workspace with restrained earthy accents.',colors:['#f5efe7','#fffaf4','#44332c','#984d35','#f1e2d7','#786053','#dfcfc1'],dark:false},
teal:{name:'Glacier & teal',note:'Cool and spacious, with clear separation between content and actions.',colors:['#edf4f4','#fcffff','#203d42','#176a72','#dcebed','#526e73','#cbdfe1'],dark:false},
plum:{name:'Graphite & lilac',note:'A dark editorial direction with soft violet emphasis.',colors:['#201e29','#2a2835','#eeeaf5','#c7b6f2','#393248','#b7afc8','#484251'],dark:true},
midnight:{name:'Midnight & ice',note:'A cool dark workspace for dense operational views and the service map.',colors:['#131e2c','#1d2b3c','#e0eaf4','#90c9ef','#293d52','#a6b7cb','#364b61'],dark:true}
};
let paletteSelection;try{paletteSelection=JSON.parse(localStorage.getItem('ipe-workspace-palette'))||'sage'}catch{paletteSelection='sage'}
if(!paletteOptions[paletteSelection])paletteSelection='sage';
function paletteStrip(){return `<section class="palette-study" aria-label="Workspace color palettes"><div class="palette-intro"><strong>Color study</strong><span>Same workspace. Six atmospheres.</span></div><div class="palette-options">${Object.entries(paletteOptions).map(([id,p])=>`<button class="palette-option" data-palette-choice="${id}" aria-pressed="${paletteSelection===id}"><span class="palette-swatches">${p.colors.slice(0,5).map(c=>`<i style="background:${c}"></i>`).join('')}</span><strong>${p.name}</strong><small>${p.dark?'Dark':'Light'} · ${paletteSelection===id?'Selected':'Preview'}</small></button>`).join('')}</div><div class="palette-description"><span>${paletteOptions[paletteSelection].note}</span><span class="palette-hex">Accent ${paletteOptions[paletteSelection].colors[3].toUpperCase()}</span></div></section>`}
function applyPalette(){const active=current.concept==='workspace';for(const node of [document.querySelector('.review-shell'),document.querySelector('#overlay')]){if(!node)continue;node.removeAttribute('style');delete node.dataset.palette;delete node.dataset.tone;if(!active)continue;const p=paletteOptions[paletteSelection];node.dataset.palette=paletteSelection;node.dataset.tone=p.dark?'dark':'light';const names=['bg','panel','text','accent','soft','muted','border'];names.forEach((n,i)=>node.style.setProperty('--'+n,p.colors[i]));node.style.setProperty('--onaccent',p.dark?'#202335':'#ffffff');node.style.setProperty('--tablehead',p.colors[0]);node.style.setProperty('--hover',p.colors[4]);node.style.setProperty('--chart',p.colors[3]);}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-palette-choice]');if(!b)return;paletteSelection=b.dataset.paletteChoice;localStorage.setItem('ipe-workspace-palette',JSON.stringify(paletteSelection));reviews.workspace={...reviews.workspace,palette:paletteSelection,paletteName:paletteOptions[paletteSelection].name};persist();render()});
